'use strict';

// MODULES //

var logger = require( 'debug' );
var params2str = require( '@stdlib/ml/base/sgd/params/to-string' );
var ddot = require( '@stdlib/blas/base/ddot' ).ndarray;
var daxpy = require( '@stdlib/blas/base/daxpy' ).ndarray;
var dscal = require( '@stdlib/blas/base/dscal' ).ndarray;
var LEARNING_RATE_METHODS = require( './learning_rate.js' );
var LOSS_FUNCTIONS = require( './loss.js' );
var DECAYS = require( './decay.js' );
var TRUNCATIONS = require( './truncation.js' );


// VARIABLES //

var debug = logger( 'ml:dsgd-trainer-squared-epsilon-insensitive' );

var MIN_SCALE = 1.0e-9;
var MAX_DLOSS = 1e12;


// MAIN //

/**
* Trains a linear model with the squared epsilon-insensitive loss via stochastic gradient descent.
*
* @private
* @param {NonNegativeInteger} M - number of samples
* @param {NonNegativeInteger} N - number of features
* @param {Float64Array} x - `M` by `N` input matrix
* @param {integer} strideX1 - stride of the first dimension of `x`
* @param {integer} strideX2 - stride of the second dimension of `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Float64Array} y - target vector
* @param {integer} strideY - stride length for `y`
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @param {Float64Array} w - weight vector
* @param {integer} strideW - stride length for `w`
* @param {NonNegativeInteger} offsetW - starting index for `w`
* @param {Float64Array} workspace - workspace array
* @param {integer} strideWS - stride length for `workspace`
* @param {NonNegativeInteger} offsetWS - starting index for `workspace`
* @param {Params} params - parameters object
* @returns {Float64Array} `w`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* // Two features, four samples; target y = 2*x0 - 1*x1:
* var x = new Float64Array( [ 1.0, 0.0, 0.0, 1.0, 1.0, 1.0, 2.0, 1.0 ] );
* var y = new Float64Array( [ 2.0, -1.0, 1.0, 3.0 ] );
* var w = new Float64Array( 2 );
* var workspace = new Float64Array( 2 );
*
* var out = dsgdTrainer(
*     'l2', 'invscaling', true, // penalty, learningRate, fitIntercept
*     4, 2, 0.0,                // M, N, l1Ratio
*     1000,                     // maxIter
*     0.02, 0.5,                // eta0, powerT
*     0.0, 1.0e-4,              // epsilon, lambda
*     0.0,                      // initial intercept
*     y, 1, 0,                  // y, strideY, offsetY
*     w, 1, 0,                  // w, strideW, offsetW
*     x, 2, 1, 0,               // x, strideX1, strideX2, offsetX
*     workspace, 1, 0           // workspace, strideWS, offsetWS
* );
*/
function dsgdTrainer( M, N, x, strideX1, strideX2, offsetX, y, strideY, offsetY, w, strideW, offsetW, workspace, strideWS, offsetWS, params ) { // eslint-disable-line max-params, max-len
	var lossFunctionParams;
	var learningRateParams;
	var penaltyParams;
	var lossFunction;
	var learningRate;
	var fitIntercept;
	var scaleFactor;
	var intercept;
	var penalty;
	var decayFn;
	var truncFn;
	var maxIter;
	var lossFn;
	var update;
	var epoch;
	var dloss;
	var lrFn;
	var eta;
	var ox;
	var oy;
	var t;
	var p;
	var i;
	var u;

	penalty = params.penalty;
	lossFunction = params.lossFunction;
	learningRate = params.learningRate;
	lrFn = LEARNING_RATE_METHODS[ learningRate ];
	lossFn = LOSS_FUNCTIONS[ lossFunction ];
	decayFn = DECAYS[ penalty ];
	truncFn = TRUNCATIONS[ penalty ];
	lossFunctionParams = params.lossFunctionParams;
	learningRateParams = params.learningRateParams;
	penaltyParams = params.penaltyParams;
	fitIntercept = params.fitIntercept;
	intercept = params.intercept;
	maxIter = params.maxIter;

	debug( 'Starting SGD trainer with %i samples and %i features', M, N );
	debug( params2str( params ) );

	/*
	* w - N (feature vector)
	* x - M*N (input vector)
	* y - M (output vector)
	*/

	/**
	 * y -> [ ... ] (vector of size M, as there are M samples)
	 * w -> [ ... ] (vector of size N, as there are N weights, one per input feature)
	 * x -> [ ... ] (vector of size MxN, as there are N features per sample, M samples)
	 */

	if ( penalty === 2 ) { // l2
		penaltyParams[ 1 ] = 0.0;
	} else if ( penalty === 1 ) { // l1
		penaltyParams[ 1 ] = 1.0;
	}

	t = 1;
	u = 0.0;
	scaleFactor = 1.0;
	for ( epoch = 1; epoch <= maxIter; epoch++ ) {
		ox = offsetX;
		oy = offsetY;
		for ( i = 0; i < M; i++ ) {
			p = ( scaleFactor*ddot( N, w, strideW, offsetW, x, strideX2, ox ) ) + intercept; // eslint-disable-line max-len

			eta = lrFn( t, learningRateParams ); // eslint-disable-line max-len

			dloss = lossFn( y[ oy ], p, lossFunctionParams ); // eslint-disable-line max-len
			if ( dloss < -MAX_DLOSS ) {
				dloss = -MAX_DLOSS;
			} else if ( dloss > MAX_DLOSS ) {
				dloss = MAX_DLOSS;
			}
			update = -eta * dloss;

			scaleFactor = decayFn( scaleFactor, eta, penaltyParams ); // eslint-disable-line max-len
			// if ( penalty === 'l2' || penalty === 'elasticnet' ) {
			// 	factor = 1.0 - ( ( 1.0 - l1Ratio ) * eta * lambda );
			// 	scaleFactor *= max( 0.0, factor );
			// }

			if ( scaleFactor < MIN_SCALE ) {
				dscal( N, scaleFactor, w, strideW, offsetW );
				scaleFactor = 1.0;
			}

			// Gradient step: w_eff += -eta*dloss*x  <=>  w_stored += (-eta*dloss/scaleFactor)*x
			// w_eff = w_stored*scaleFactor
			daxpy( N, update/scaleFactor, x, strideX2, ox, w, strideW, offsetW ); // eslint-disable-line max-len

			if ( fitIntercept ) {
				intercept += update;
			}

			u = truncFn( N, u, scaleFactor, w, strideW, offsetW, workspace, strideWS, offsetWS, penaltyParams ); // eslint-disable-line max-len
			// if ( penalty === 'l1' || penalty === 'elasticnet' ) {
			// 	u += ( l1Ratio * eta * lambda );
			// 	l1Penalty( N, u, scaleFactor, w, strideW, offsetW, workspace, strideWS, offsetWS ); // eslint-disable-line max-len
			// }

			t += 1;
			ox += strideX1;
			oy += strideY;
		}
		debug( 'Epoch %d done...', epoch );
	}

	// Fold any residual scale back into the weights so `w` holds effective values:
	// sklearn does w.reset_scale()
	if ( scaleFactor !== 1 ) {
		dscal( N, scaleFactor, w, strideW, offsetW );
		scaleFactor = 1.0;
	}

	debug( 'Finished SGD trainer.' );

	if ( fitIntercept ) {
		w[ offsetW + ( ( strideW * N ) + 1 ) ] = intercept; // We expect consumer to pass an array of size N+1 if they set `fitIntercept = true`
		// TODO: Do a size check in sgd_trainer.js
		// if `fitIntercept = true`, check if its size is N+1
	}
	return w;
}


// EXPORTS //

module.exports = dsgdTrainer;
